/* Kaderkompass – Anleitung (wird aus src/anleitung gebaut, nicht von Hand ändern) */
/* Kaderkompass – Anleitung: Darstellung (in der App und für das PDF). Daten: PSVAnleitung.DATEN */
(function (root) {
  'use strict';
  var A = root.PSVAnleitung = root.PSVAnleitung || {};
  function h(s) { return String(s === null || s === undefined ? '' : s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
  function norm(s) { return String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''); }
  A.treffer = function (k, q) { if (!q) return true; var t = norm([k.titel, k.tipp].concat(k.schritte).join(' ')); return norm(q).split(/\s+/).filter(Boolean).every(function (w) { return t.indexOf(w) >= 0; }); };
  A.karteFuer = function (tab) { var r = null; (A.DATEN.karten || []).forEach(function (k) { if (!r && (k.kontext || []).indexOf(tab) >= 0) r = k.id; }); return r; };
  A.karteHtml = function (k) {
    return '<section class="anl-karte card" id="anl-' + h(k.id) + '"><h2>' + h(k.titel) + '</h2><div class="anl-inhalt">' + (A.BILDER[k.id] ? '<img class="anl-bild" alt="" src="' + A.BILDER[k.id] + '">' : '') +
      '<div><ol class="anl-schritte">' + k.schritte.map(function (s) { return '<li>' + h(s) + '</li>'; }).join('') + '</ol><div class="anl-tipp"><b>Tipp:</b> ' + h(k.tipp) + '</div></div></div></section>';
  };
  A.neuHtml = function () { return '<section class="anl-karte card" id="anl-neu"><h2>Was ist neu</h2>' + A.DATEN.neu.map(function (v) { return '<div class="anl-ver"><b>Version ' + h(v.version) + '</b><ul>' + v.punkte.map(function (p) { return '<li>' + h(p) + '</li>'; }).join('') + '</ul></div>'; }).join('') + '</section>'; };
  A.CSS = '.anl-inhalt{display:flex;gap:12px;align-items:flex-start}.anl-bild{width:42%;max-width:220px;border-radius:10px;border:1px solid #d5dcd6;flex:none}.anl-schritte{margin:0 0 8px;padding-left:22px}.anl-schritte li{margin:4px 0}' +
    '.anl-tipp{background:#E8F5E9;border-left:4px solid #1B5E20;padding:6px 8px;border-radius:6px;font-size:.95em}.anl-ver ul{margin:2px 0 8px;padding-left:20px}.anl-inhalt>div{flex:1}@media (max-width:420px){.anl-inhalt{flex-direction:column}.anl-bild{width:100%;max-width:none}}';
  A.dokument = function (version) {   // eigenständiges HTML für das PDF (A4, App-Design)
    return '<!DOCTYPE html><html lang="de"><head><meta charset="utf-8"><title>' + h(A.DATEN.titel) + '</title><style>*{box-sizing:border-box}body{font:12.5px/1.45 Roboto,Arial,sans-serif;color:#1d2320;margin:0}' +
      'header{background:#1B5E20;color:#fff;padding:14px 18px;border-radius:10px;margin-bottom:12px}header h1{margin:0;font-size:22px}header div{opacity:.85}.card{border:1px solid #d5dcd6;border-radius:12px;padding:10px 14px;margin:0 0 10px;break-inside:avoid}' +
      '.card h2{color:#1B5E20;font-size:16px;margin:0 0 6px}.anl-bild{width:150px!important}.inhalt{columns:1}' + A.CSS + '@page{size:A4 portrait;margin:12mm}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}.fuss{text-align:center;color:#5f6b63;font-size:10px;margin-top:8px}</style></head><body>' +
      '<header><h1>' + h(A.DATEN.titel) + '</h1><div>Version ' + h(version) + ' · ' + h(A.DATEN.intro) + '</div></header><section class="card"><h2>Inhalt</h2><ol>' + A.DATEN.karten.map(function (k) { return '<li>' + h(k.titel) + '</li>'; }).join('') + '<li>Was ist neu</li></ol></section>' +
      A.DATEN.karten.map(A.karteHtml).join('') + A.neuHtml() + '<div class="fuss">Kaderkompass · © MLN Consulting · mlnc.net</div></body></html>';
  };
})(typeof self !== 'undefined' ? self : this);

(function(A){A.DATEN={"titel":"Kaderkompass – Anleitung","intro":"Kurz und knapp: Jede Karte zeigt eine Aufgabe in wenigen Schritten. Oben suchen oder auf ein Thema tippen.","karten":[{"id":"start","titel":"In 2 Minuten startklar","kontext":["mehr"],"schritte":["Android: Die Datei Kaderkompass.apk öffnen und „Installieren“ tippen (einmalig „Unbekannte Apps erlauben“ bestätigen).","iPad/iPhone: Die Web-App in Safari öffnen, dann Teilen-Symbol → „Zum Home-Bildschirm“.","Mit deiner E-Mail und deinem Passwort anmelden.","Unter Mehr → „Cloud & Team verwalten“ den Team-Code vom Trainer eingeben, dann das Team-Passwort.","Fertig: Die Mannschaft erscheint und bleibt auf allen Geräten gleich."],"tipp":"Das Team-Passwort gut aufheben – ohne es kann niemand die Daten lesen, auch nicht der Betreiber.","bild":{"nav":"setTab('mehr')","marks":[["#cloudM","4"]]}},{"id":"spieltag","titel":"Spieltag anlegen & Zusagen","kontext":["spieltag"],"schritte":["Unten auf „Spieltage“ tippen, dann „Neuer Spieltag“: Datum, Gegner, Heim/Auswärts eintragen.","Zusagen pro Kind antippen: Zugesagt, Abgesagt oder Offen.","Oder aus SpielerPlus übernehmen: Mehr → „SpielerPlus importieren“ → Datei wählen → Vorschau prüfen.","Wichtig: Danach „Übernehmen“ tippen – erst dann sind die Zusagen gespeichert."],"tipp":"Neue Spieltage übernehmen die Zusagen vom letzten Spieltag – nur noch Änderungen antippen.","bild":{"nav":"setTab('spieltag')","marks":[["text:Neuer Spieltag","1"]]}},{"id":"aufstellung","titel":"Aufstellung & Formation","kontext":["aufstellung","ranking"],"schritte":["Den Spieltag öffnen. Die App schlägt eine Startelf vor.","Auf „Formation“ tippen und z. B. 2-3-1 oder 3-2-1 wählen.","Kinder per Finger von der Bank auf eine Position ziehen (oder zwei Positionen tauschen)."],"tipp":"Auch nach dem Spiel lässt sich die Startelf noch korrigieren – die Minuten rechnen sich neu.","bild":{"nav":"openSt(); ","marks":[["#fsForm","2"]]}},{"id":"live","titel":"Live-Modus beim Spiel","kontext":[],"schritte":["Im Spieltag „Live-Modus: Spiel starten“ tippen, dann „Anpfiff“.","Tore, Gegentore und Notizen über die großen Knöpfe eintragen – die Minute kommt automatisch.","Wechsel: Kind von der Bank auf das Kind auf dem Platz ziehen.","Halbzeit und Abpfiff tippen. Danach entsteht die Zusammenfassung."],"tipp":"Der Bildschirm bleibt an. Die Uhr läuft auch weiter, wenn das Handy kurz gesperrt ist.","bild":{"nav":"openSt(1); go('live')","marks":[["#lvStart","1"]]}},{"id":"sr","titel":"Schiedsrichter-Modus & Bericht","kontext":[],"schritte":["Im Spieltag „Schiedsrichter-Modus“ öffnen und unten die Spieldaten eintragen (Name, Spielklasse, Spielnummer).","„Anpfiff“: Die Uhr zählt die Halbzeit herunter und piept am Ende.","Tore beider Teams, Strafen (Ermahnung, Gelb, Zeitstrafe, Rot), Verletzungen und Vorkommnisse antippen.","Nach dem Abpfiff „Als PDF speichern“ oder „Teilen“ für den Bericht."],"tipp":"Live-Modus und Schiedsrichter-Modus nutzen dieselbe Uhr. Maßgeblich bleibt der Spielbericht im DFBnet.","bild":{"nav":"openSt(1); go('sr')","marks":[["#srAn","2"],["[data-srtor=\"heim\"]","3"]]}},{"id":"nachher","titel":"Nach dem Spiel","kontext":[],"schritte":["Im Spieltag „Spielbewertung“: jedes Kind mit 1 bis 5 bewerten.","„Spielzusammenfassung“ prüfen und bei Bedarf Text anpassen.","„Elternbericht“ tippen: Notiz kurz anpassen, dann als Bild in die Eltern-Gruppe teilen."],"tipp":"Der Elternbericht zeigt keine Noten und bei Gegentoren keine Namen.","bild":{"nav":"openSt(); go('zusammenfassung')","marks":[["#zsEltern","3"]]}},{"id":"messungen","titel":"Messungen mit Timern","kontext":["messungen"],"schritte":["Unter „Messungen“ einen neuen Messtermin anlegen und die Tests wählen.","Abhaken, wer mitmacht, und „Test starten“ tippen.","Den Timer des Tests nutzen: Stoppuhr (Sprint), Countdown mit Rundenzähler (Lauf), Treffer/Daneben (Pass), Zähler (Jonglieren).","Das Ergebnis landet direkt beim Kind – danach kommt automatisch das nächste Kind.","1-gegen-1: Angreifer und Verteidiger wählen, „Start“, nach dem Pfiff das Ergebnis tippen."],"tipp":"Ton laut stellen – die Pieptöne sind für draußen auf dem Platz gemacht.","bild":{"nav":"openMess()","marks":[["#mwLos","3"]]}},{"id":"taktik","titel":"Taktiktafel","kontext":[],"schritte":["Im Spieltag die Taktiktafel öffnen – die aktuelle Aufstellung ist schon drauf.","Spieler und Ball mit dem Finger verschieben, Pfeile zeichnen.","Als Bild oder PDF speichern oder teilen."],"tipp":"Mehrere Spielzüge nacheinander speichern und mit ▶ abspielen.","bild":{"nav":"openSt()","marks":[["#tkKarte","1"]]}},{"id":"praes","titel":"Präsentation & PDF","kontext":[],"schritte":["Mehr → „Präsentation erstellen“.","Version wählen: Trainer (mit Werten) oder Mannschaft (ohne Werte).","Vollbild zeigen oder „Als PDF speichern“ bzw. „Teilen“."],"tipp":"Für die Kabine die Mannschafts-Version nehmen – dort stehen keine Noten.","bild":{"nav":"go('praes')","marks":[]}},{"id":"wetter","titel":"Wetter & Navigation","kontext":[],"schritte":["Im Spieltag zeigt die Wetter-Karte die Vorhersage für die Spielzeit.","Auf die Adresse des Platzes tippen – Google Maps startet die Route."],"tipp":"Das Wetter aktualisiert sich bis zum Spielende von selbst.","bild":{"nav":"openSt()","marks":[["#wtKarte","1"]]}},{"id":"liga","titel":"Liga","kontext":["liga"],"schritte":["Unten auf „Liga“ tippen.","Spielplan und Tabelle kommen direkt von fussball.de."],"tipp":"Braucht Internet. Ohne Netz bleibt der Rest der App voll nutzbar.","bild":{"nav":"setTab('liga')","marks":[]}},{"id":"sicherung","titel":"Sicherung & Cloud","kontext":[],"schritte":["Mit Cloud wird jede Änderung automatisch verschlüsselt gesichert.","Zusätzlich ab und zu unter Mehr → „Exportieren“ eine Sicherungsdatei speichern.","Zum Wiederherstellen: Mehr → „Importieren“ und die Datei wählen."],"tipp":"Das Wolken-Symbol oben zeigt, ob alles gespeichert ist.","bild":{"nav":"setTab('mehr')","marks":[["#exp","2"]]}},{"id":"spieler","titel":"Spieler anlegen & archivieren","kontext":["kader"],"schritte":["Unter „Kader“ auf „+ Neuer Spieler“ tippen, Name, Nummer und Position eintragen, Foto optional.","Ein Kind antippen, um Werte und Positionen zu ändern.","Wer die Mannschaft verlässt: im Spielerbogen „Spieler entfernen“ – das Kind wird archiviert, alte Spiele bleiben erhalten."],"tipp":"Archivierte Kinder lassen sich unter „Ehemalige Spieler“ jederzeit zurückholen.","bild":{"nav":"setTab('kader')","marks":[["text:Neuer Spieler","1"]]}},{"id":"einstellungen","titel":"Einstellungen & Trainingstage","kontext":[],"schritte":["Unten auf „Mehr“ tippen.","Bei „Trainingstage“ die Tage antippen, an denen ihr trainiert.","Weitere Einstellungen wie Saisonbeginn findest du auf derselben Seite."],"tipp":"Die Trainingstage nutzt der Elternbericht für den Satz zum nächsten Training.","bild":{"nav":"setTab('mehr'); setTimeout(function(){ var x=[...document.querySelectorAll('h2')].find(h=>/Trainingstage/.test(h.textContent)); if(x) x.scrollIntoView(); },10)","marks":[["text:Trainingstage","2"]]}}],"neu":[{"version":"2.8.1","punkte":["Neue Anleitung in der App: „?“ oben rechts, unter Mehr und als PDF."]},{"version":"2.8","punkte":["Timer für alle Messungen: Stoppuhr, Lauf-Countdown mit Rundenzähler, Treffer-Zähler, Jonglier-Zähler, Reaktionssignal.","Schiedsrichter-Modus mit Halbzeit-Countdown, Strafen und Zeitstrafen-Uhr.","Schiedsrichterbericht als PDF."]},{"version":"2.7.2","punkte":["1-gegen-1: Teilnehmer abhaken, faire Rotation bis 6 Duelle je Rolle."]},{"version":"2.7.1","punkte":["1-gegen-1: Duell-Timer mit lauten Pieptönen und Vibration."]},{"version":"2.7","punkte":["Neuer Test 1-gegen-1 (Angriff und Abwehr).","Auswahllisten zeigen nur Kinder dieses Spieltags."]},{"version":"2.6.1","punkte":["Trainingstage einstellbar, Elternbericht nennt das nächste Training richtig."]},{"version":"2.6","punkte":["Elternbericht als Bild oder PDF zum Teilen."]},{"version":"2.5.2","punkte":["PDF der Präsentation und anderer Berichte korrigiert."]},{"version":"2.5","punkte":["Neuer Name Kaderkompass, neues Symbol, Impressum und Datenschutz."]},{"version":"2.4","punkte":["Schneller und kleine Verbesserungen."]},{"version":"2.3","punkte":["Taktiktafel je Spieltag.","Wetter für die Spielzeit und Navigation zum Platz."]},{"version":"2.2","punkte":["Web-App für iPad und iPhone, auch offline."]},{"version":"2.1","punkte":["Zusagen aus SpielerPlus übernehmen."]},{"version":"2.0","punkte":["Verschlüsselte Cloud: mehrere Trainer, ein Team."]},{"version":"1.9","punkte":["Liga-Seite mit Spielplan und Tabelle von fussball.de."]},{"version":"1.8","punkte":["Spiele dauern standardmäßig 2 × 30 Minuten."]},{"version":"1.6","punkte":["Gegner-Datei mit Direktvergleich und Notizen."]},{"version":"1.5","punkte":["Präsentation für Trainer und Mannschaft."]},{"version":"1.4","punkte":["Messungen mit Altersbändern und Verlauf."]},{"version":"1.3","punkte":["Spieler archivieren statt löschen."]},{"version":"1.2","punkte":["Mehr Formationen, neue Spieler einfach anlegen."]},{"version":"1.1","punkte":["Spieltage, Live-Modus, Spielbewertung."]},{"version":"1.0","punkte":["Erste Version: Kader, Ranking, Aufstellung."]}]};A.BILDER={"start":"data:image/jpeg;base64,","spieltag":"data:image/jpeg;base64,","aufstellung":"data:image/jpeg;base64,","live":"data:image/jpeg;base64,","sr":"data:image/jpeg;base64,","nachher":"data:image/jpeg;base64,","messungen":"data:image/jpeg;base64,","taktik":"data:image/jpeg;base64,","praes":"data:image/jpeg;base64,","wetter":"data:image/jpeg;base64,","liga":"data:image/jpeg;base64,","sicherung":"data:image/jpeg;base64,","spieler":"data:image/jpeg;base64,","einstellungen":"data:image/jpeg;base64,"};A.VERSION="2.8.1";})(self.PSVAnleitung);
